<?php
require 'includes/bootstrap.php';if(empty($_SESSION['role']))go('student_login.php');$role=$_SESSION['role'];$manager=can_manage_content();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$manager){http_response_code(403);exit('Not allowed.');}$action=$_POST['action']??'add';$id=(int)($_POST['id']??0);
 if($action==='delete'){$q=$pdo->prepare('SELECT * FROM study_materials WHERE id=?');$q->execute([$id]);$m=$q->fetch();if($m&&($role==='admin'||(int)$m['faculty_id']===(int)$_SESSION['user_id'])){if(is_file(__DIR__.'/'.$m['file_path']))@unlink(__DIR__.'/'.$m['file_path']);$pdo->prepare('DELETE FROM study_materials WHERE id=?')->execute([$id]);flash('Study material deleted.');}go('study-material.php');}
 $title=trim($_POST['title']??'');$subject=trim($_POST['subject']??'');$desc=trim($_POST['description']??'');if(!$title||!$subject||empty($_FILES['material']['tmp_name'])||$_FILES['material']['error']!==UPLOAD_ERR_OK){flash('Complete all required fields and choose a file.');go('study-material.php');}
 if($_FILES['material']['size']>25*1024*1024){flash('File must be 25 MB or smaller.');go('study-material.php');}$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['material']['tmp_name']);$allowed=['application/pdf'=>'pdf','text/plain'=>'txt','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/vnd.ms-powerpoint'=>'ppt','application/vnd.openxmlformats-officedocument.presentationml.presentation'=>'pptx','application/vnd.ms-excel'=>'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx'];if(!isset($allowed[$mime])){flash('Unsupported file. Upload PDF, DOC/DOCX, PPT/PPTX, XLS/XLSX or TXT.');go('study-material.php');}
 $original=basename($_FILES['material']['name']);$filename=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$path='uploads/materials/'.$filename;if(!move_uploaded_file($_FILES['material']['tmp_name'],__DIR__.'/'.$path)){flash('Upload failed.');go('study-material.php');}$fid=$role==='faculty'?$_SESSION['user_id']:null;$q=$pdo->prepare('INSERT INTO study_materials(title,description,subject,file_path,original_name,faculty_id) VALUES(?,?,?,?,?,?)');$q->execute([$title,$desc,$subject,$path,$original,$fid]);flash('Study material uploaded.');go('study-material.php');}
$q=$pdo->query("SELECT m.*,COALESCE(f.name,'Administrator') faculty_name FROM study_materials m LEFT JOIN faculty f ON f.id=m.faculty_id ORDER BY m.created_at DESC");$materials=$q->fetchAll();page_start('Study Materials');?>
<div class="vc-card"><h2>Study Materials</h2><p>Download notes, presentations and other course resources.</p><?php if($manager): ?><hr><h4>Upload learning material</h4><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="form-group mb-3"><label>Title</label><input class="form-control" name="title" maxlength="200" required></div><div class="form-group mb-3"><label>Subject</label><input class="form-control" name="subject" required></div><div class="form-group mb-3"><label>Description</label><textarea class="form-control" name="description" rows="3"></textarea></div><div class="form-group mb-3"><label>File (max 25 MB)</label><input class="form-control" type="file" name="material" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt" required></div><button class="btn btn-primary">Upload material</button></form><?php endif; ?></div>
<?php foreach($materials as $m): ?><div class="vc-card"><h4><?=e($m['title'])?></h4><p><b><?=e($m['subject'])?></b> · By <?=e($m['faculty_name'])?> · <?=e($m['created_at'])?></p><p><?=nl2br(e($m['description']))?></p><a class="btn btn-outline-primary" href="<?=e($m['file_path'])?>" download="<?=e($m['original_name'])?>">Download <?=e($m['original_name'])?></a><?php if($manager&&($role==='admin'||(int)$m['faculty_id']===(int)$_SESSION['user_id'])): ?><form class="mt-2" method="post" onsubmit="return confirm('Delete this material?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-sm btn-danger">Delete</button></form><?php endif; ?></div><?php endforeach; if(!$materials): ?><div class="vc-card">No study materials have been uploaded yet.</div><?php endif; ?><?php page_end(); ?>